"805 :   @Override
806 :   protected CompilerOptions createOptions() {
807 :     CompilerOptions options = new CompilerOptions();
808 :     if (flags.processJqueryPrimitives) {
809 :       options.setCodingConvention(new JqueryCodingConvention());
810 :     } else {
811 :       options.setCodingConvention(new ClosureCodingConvention());
812 :     }
813 : 
814 :     options.setExtraAnnotationNames(flags.extraAnnotationName);
815 : 
816 :     CompilationLevel level = flags.compilationLevel;
817 :     level.setOptionsForCompilationLevel(options);
818 : 
819 :     if (flags.debug) {
820 :       level.setDebugOptionsForCompilationLevel(options);
821 :     }
822 : 
823 :     if (flags.useTypesForOptimization) {
824 :       level.setTypeBasedOptimizationOptions(options);
825 :     }
826 : 
827 :     if (flags.generateExports) {
828 :       options.setGenerateExports(flags.generateExports);
829 :     }
830 : 
831 :     WarningLevel wLevel = flags.warningLevel;
832 :     wLevel.setOptionsForWarningLevel(options);
833 :     for (FormattingOption formattingOption : flags.formatting) {
834 :       formattingOption.applyToOptions(options);
835 :     }
836 : 
837 :     options.closurePass = flags.processClosurePrimitives;
838 : 
839 :     options.jqueryPass = CompilationLevel.ADVANCED_OPTIMIZATIONS == level &&
840 :         flags.processJqueryPrimitives;
841 : 
842 :     options.angularPass = flags.angularPass;
843 : 
844 :     if (!flags.translationsFile.isEmpty()) {
845 :       try {
846 :         options.messageBundle = new XtbMessageBundle(
847 :             new FileInputStream(flags.translationsFile),
848 :             flags.translationsProject);
849 :       } catch (IOException e) {
850 :         throw new RuntimeException("Reading XTB file", e);
851 :       }
852 :     } else if (CompilationLevel.ADVANCED_OPTIMIZATIONS == level) {
853 :       // In SIMPLE or WHITESPACE mode, if the user hasn't specified a
854 :       // translations file, they might reasonably try to write their own
855 :       // implementation of goog.getMsg that makes the substitution at
856 :       // run-time.
857 :       //
858 :       // In ADVANCED mode, goog.getMsg is going to be renamed anyway,
859 :       // so we might as well inline it. But shut off the i18n warnings,
860 :       // because the user didn't really ask for i18n.
861 :       options.messageBundle = new EmptyMessageBundle();
862 :     }
863 : 
864 :     return options;
865 :   }"

